package cn.breezeth.kaleidoscope_grilling;
import net.minecraft.ChatFormatting;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.*;import net.minecraftforge.registries.ForgeRegistries;import java.util.*;
public final class SeasoningTooltip{public static void append(ItemStack stack,List<Component>tooltip){List<String>v=SeasoningData.get(stack);tooltip.add(Component.translatable("tooltip.kaleidoscope_grilling.seasoning_capacity_detail",v.size(),8,8-v.size()).withStyle(ChatFormatting.GRAY));String state=v.isEmpty()?"empty":stack.is(ModItems.SPECIAL_SEASONING.get())?"finished":"pending";tooltip.add(Component.translatable("tooltip.kaleidoscope_grilling.seasoning_state."+state).withStyle(ChatFormatting.GRAY));for(String id:v){Item item=ForgeRegistries.ITEMS.getValue(new ResourceLocation(id));if(item!=null)tooltip.add(Component.literal("- ").append(item.getDescription()).withStyle(ChatFormatting.DARK_GRAY));}List<Component>effects=SeasoningEffects.describe(v);if(!effects.isEmpty()){tooltip.add(Component.empty());tooltip.add(Component.translatable("tooltip.kaleidoscope_grilling.seasoning_effects").withStyle(ChatFormatting.GOLD));effects.forEach(c->tooltip.add(c.copy().withStyle(ChatFormatting.DARK_GRAY)));}}private SeasoningTooltip(){}}
